// Parses an unauthenticated chat message into an auth action.
// Everything here is deterministic: no LLM ever sees credentials.
const USERNAME_RE = /^[A-Za-z0-9_]{3,32}$/;
const HELP = "Welcome to **Persona**, your personal AI news digest.\n\nTo get started:\n- `/register <username> <password> accept` to create an account\n- `/login <username> <password>` to log in\n\nUsername: 3 to 32 letters, digits or underscores. Password: 8 to 72 characters, no spaces.\n\n**Privacy:** Persona only stores your username, a hashed password, your email, your topics and your preferred delivery time, in order to send you your newsletter. You can view, pause or delete your data at any time from this chat. Adding `accept` to the register command means you agree to this.";

const sessionId = String($json.sessionId ?? '');
const input = String($json.chatInput ?? '').trim();
const parts = input.split(/\s+/);
const command = (parts[0] || '').toLowerCase();

const result = (action, extra = {}) => ({ json: { action, sessionId, ...extra } });
const reject = (reply) => result('reject', { reply });

if (!sessionId) return reject('Missing chat session. Please reload the chat.');

function checkCredentials(username, password) {
  if (!USERNAME_RE.test(username || '')) {
    return 'Invalid username: use 3 to 32 letters, digits or underscores.';
  }
  const bytes = Buffer.byteLength(password || '', 'utf8');
  if (bytes < 8 || bytes > 72) {
    return 'Invalid password: use 8 to 72 characters, without spaces.';
  }
  return null;
}

if (command === '/register') {
  if (parts.length !== 4 || parts[3].toLowerCase() !== 'accept') {
    return reject(
      'To create an account, type:\n`/register <username> <password> accept`\n\n' +
      'The word `accept` confirms that you agree to the privacy notice below.\n\n' + HELP
    );
  }
  const error = checkCredentials(parts[1], parts[2]);
  if (error) return reject(error);
  return result('register', { username: parts[1], password: parts[2] });
}

if (command === '/login') {
  if (parts.length !== 3) {
    return reject('To log in, type:\n`/login <username> <password>`');
  }
  const error = checkCredentials(parts[1], parts[2]);
  // Same message as a wrong password: don't reveal what was wrong.
  if (error) return reject('Invalid credentials or too many attempts. Please try again later.');
  return result('login', { username: parts[1], password: parts[2] });
}

return reject(HELP);
